 public static void main(String[]args)throws Exception{try(AnnotationConfigApplicationContext c=new AnnotationConfigApplicationContext(Config.class)){JdbcTemplate db=c.getBean(JdbcTemplate.class);WalletService w=c.getBean(WalletService.class);MerchantApiService api=c.getBean(MerchantApiService.class);FinanceService f=c.getBean(FinanceService.class);long merchant=System.currentTimeMillis(),user=merchant+1;String day=LocalDate.now(ZoneId.of("Asia/Shanghai")).toString(),occurred=OffsetDateTime.now(ZoneId.of("Asia/Shanghai")).withNano(0).toString(),card="CC"+UUID.randomUUID().toString().replace("-","").toUpperCase(Locale.ROOT),student="FIN"+user;db.update("insert into sys_user(user_id,login_name,user_name,status,del_flag) values(?,?,'对账测试','0','0')",user,student);db.update("insert into campus_card(user_id,card_no) values(?,?)",user,card);w.issue(user);db.update("insert into campus_person_identity(user_id,identity_no) values(?,'11010519491231002X')",user);db.update("insert into campus_merchant(id,name,active) values(?,'对账测试商户',1)",merchant);w.trade(user,"RECHARGE",new BigDecimal("100.00"),null,null,UUID.randomUUID().toString(),1);api.ensure(merchant);api.configure(merchant,true,true,true,"",1);Map<String,Object> cred=db.queryForMap("select c.*,m.name from campus_api_credential c join campus_merchant m on m.id=c.merchant_id where c.merchant_id=?",merchant);String uuid=(String)cred.get("public_id"),serial="POS"+UUID.randomUUID().toString();Map<String,String> p=new LinkedHashMap<>();p.put("merchantId",uuid);p.put("merchantName","对账测试商户");p.put("merchantSerialNo",serial);p.put("cardNo",card);p.put("amount","10.00");p.put("occurredAt",occurred);p.put("location","食堂");p.put("description","午餐");String order=(String)api.payment(cred,p,"PAY").get("campusOrderNo");long pay=db.queryForObject("select ledger_id from campus_api_order where order_no=?",Long.class,order);long refund=w.trade(user,"REFUND",new BigDecimal("2.00"),null,pay,UUID.randomUUID().toString(),1);String voucher=(String)w.receipt(refund).get("transaction_no"),refundSerial="REF"+UUID.randomUUID().toString();String payRow=uuid+","+serial+","+order+",PAY,10.00,SUCCESS,"+occurred+",,\r\n",refundRow=uuid+","+refundSerial+","+order+",REFUND,2.00,SUCCESS,"+occurred+","+serial+","+voucher+"\r\n";String internal=f.internal(day,day,1);check(((Number)f.batch(internal).get("difference_count")).intValue()==0,"internal balances and successful orders reconcile");Map<String,Object> orderLine=db.queryForMap("select * from campus_finance_line where batch_id=? and campus_order=?",internal,order);String snap=String.valueOf(orderLine.get("snapshot"));check(snap.contains(serial)&&snap.contains("system_serial")&&snap.contains("对账测试商户")&&snap.contains("午餐"),"internal order snapshot includes linked serial merchant and description");check(db.queryForObject("select count(*) from campus_finance_line where batch_id=? and category='DIRECT_LEDGER'",Integer.class,internal)>0,"unlinked direct ledger entries preserved");Map<String,Object> filtered=f.lines(internal,false,null,1,"ORDERS");check(((java.util.List<Map<String,Object>>)filtered.get("rows")).stream().noneMatch(x->"WALLET".equals(x.get("category"))),"order detail excludes wallet balance checks");check(((Number)f.lines(internal,false,null,1,"WALLET").get("total")).intValue()>0,"wallet balance checks remain separately available");check(new String(f.export(internal,1),java.nio.charset.StandardCharsets.UTF_8).contains("午餐"),"internal export preserves transaction summary");String matched=f.importBill(merchant,day,day,csv(payRow+refundRow),1);check(((Number)f.batch(matched).get("difference_count")).intValue()==0,"merchant payment and refund vouchers match");Map<String,Object>b=f.batch(matched);check(Arrays.equals((byte[])f.file((String)b.get("source_file_id")).get("content"),csv(payRow+refundRow).data),"original bill preserved with snapshot");String bad=f.importBill(merchant,day,day,csv(payRow.replace(",10.00,",",11.00,")+refundRow),1);List<Map<String,Object>> differences=db.queryForList("select * from campus_finance_line where batch_id=? and difference_code<>'MATCH'",bad);check(differences.size()==1&&"TRADE_MISMATCH".equals(differences.get(0).get("difference_code")),"amount mismatch detected");long line=((Number)differences.get(0).get("id")).longValue();reject(()->f.archive(bad,2),"unresolved batch cannot archive");f.handle(line,"已核实商户账单金额误录，保留差异快照",null,1);reject(()->f.review(line,true,"本人复核",1),"handler cannot review own work");f.review(line,true,"已独立核对原消费与凭证",2);f.archive(bad,2);check("ARCHIVED".equals(f.batch(bad).get("status")),"reviewed batch archives without rewriting discrepancy");reject(()->f.handle(line,"修改归档",null,1),"archived batch immutable");check(new BigDecimal("92.00").compareTo((BigDecimal)w.info(user).get("balance"))==0,"reconciliation and review never modify wallet funds");String duplicate=f.importBill(merchant,day,day,csv(payRow+payRow+refundRow),1);check(db.queryForObject("select count(*) from campus_finance_line where batch_id=? and difference_code='DUPLICATE'",Integer.class,duplicate)==2,"duplicate merchant serials detected");String missing=f.importBill(merchant,day,day,csv(payRow),1);check(db.queryForObject("select count(*) from campus_finance_line where batch_id=? and difference_code='PLATFORM_ONLY' and trade_type='REFUND'",Integer.class,missing)==1,"platform-only refund identified");String only=f.importBill(merchant,day,day,csv(payRow+refundRow+payRow.replace(serial,"NO"+UUID.randomUUID().toString()).replace(order,"")),1);check(db.queryForObject("select count(*) from campus_finance_line where batch_id=? and difference_code='MERCHANT_ONLY'",Integer.class,only)==1,"merchant-only transaction identified");long before=db.queryForObject("select count(*) from campus_finance_batch",Long.class);reject(()->f.importBill(merchant,day,day,csv(payRow.replace(uuid,UUID.randomUUID().toString())),1),"wrong merchant bill rejected");check(db.queryForObject("select count(*) from campus_finance_batch",Long.class)==before,"invalid import leaves no partial batch");byte[] export=f.export(matched,1);check(new String(export,java.nio.charset.StandardCharsets.UTF_8).contains(serial),"full result export includes business identifiers");String repeat=f.importBill(merchant,day,day,csv(payRow+refundRow),1);check(!repeat.equals(matched)&&f.batch(matched).get("source_hash").equals(f.batch(repeat).get("source_hash")),"rerun preserves prior version and input hash");db.update("update campus_ledger set amount=11 where id=?",pay);String corrupt=f.internal(day,day,1);check(((Number)f.batch(corrupt).get("difference_count")).intValue()>=2,"internal detects balance and order-ledger discrepancies");db.update("update campus_ledger set amount=10 where id=?",pay);
 try(org.apache.poi.ss.usermodel.Workbook book=new org.apache.poi.xssf.usermodel.XSSFWorkbook()){org.apache.poi.ss.usermodel.Sheet sheet=book.createSheet("账单");String[] header=FinanceService.HEADER.split(","),values=payRow.trim().split(",",-1);org.apache.poi.ss.usermodel.Row h=sheet.createRow(0),v=sheet.createRow(1);for(int i=0;i<9;i++){h.createCell(i).setCellValue(header[i]);v.createCell(i).setCellValue(values[i]);}ByteArrayOutputStream out=new ByteArrayOutputStream();book.write(out);check(f.parse(new FileData("bill.xlsx",out.toByteArray())).size()==2,"XLSX bill supported");v.getCell(4).setCellFormula("1+1");out.reset();book.write(out);byte[] formula=out.toByteArray();reject(()->f.parse(new FileData("bill.xlsx",formula)),"formula cells rejected");}
 reject(()->f.parse(new FileData("bad.csv",new byte[]{(byte)0xc3})),"malformed UTF8 rejected");System.out.println("PASS TOTAL "+n);}}
